    model.component("comp1").variable("var6")
         .set("h_ave_all", "h_ave_negCC+h_ave_neg+h_ave_sep+h_ave_pos+h_ave_posCC", "\u603b\u4f53\u5e73\u5747\u4ea7\u70ed\u7387");
