  private static String[][] concatTables(String[][]... chunks) {
    int total = 0;
    for (String[][] chunk : chunks) {
      total += chunk.length;
    }
    String[][] table = new String[total][];
    int offset = 0;
    for (String[][] chunk : chunks) {
      System.arraycopy(chunk, 0, table, offset, chunk.length);
      offset += chunk.length;
    }
    return table;
  }

  private static Model buildModel() {
    Model model = run();
    model = run2(model);
    model = run3(model);
    model = run4(model);
    model = run5(model);
    model = run6(model);
    model = run7(model);
    model = run8(model);
    model = run9(model);
    model = run10(model);
    model = run11(model);
    model = run12(model);
    model = run13(model);
    model = run14(model);
    model = run15(model);
    return model;
  }

  private static void configureCase(Model model, String[] spec) {
    boolean charge = spec[CASE_DIRECTION].equals("charge");

    model.param().set("L_neg", spec[CASE_L_NEG_UM] + "[um]");
    model.param().set("L_pos", spec[CASE_L_POS_UM] + "[um]");
    model.param().set("den_neg", spec[CASE_DEN_NEG] + "[mg/mm^2]");
    model.param().set("den_pos", spec[CASE_DEN_POS] + "[mg/mm^2]");
    model.param().set("T", "25[degC]");
    model.param().set("C", spec[CASE_RATE]);
    model.param("par3").set("SOC", spec[CASE_SOC]);

    model.study("std1").feature("param").active(false);
    model.study("std1").feature("param2").active(false);
    model.study("std1").feature("param3").active(false);
    model.study("std1").feature("time").set("tlist", "range(0,20/C,20000/C)");
    model.sol("sol5").feature("t1").set("tlist", "range(0,20/C,20000/C)");

    model.component("comp1").physics("liion").feature("ec1").set(
        "Its",
        charge ? "i_1C*C*3.2[V]/(comp1.vol)" : "-i_1C*C*3.2[V]/(comp1.vol)");
    model.sol("sol5").feature("t1").feature("st1").set(
        "stopcondActive",
        charge ? new String[]{"on", "off"} : new String[]{"off", "on"});
  }

  private static void exportCase(Model model, String[] spec) {
    String base = "codex_" + caseName(spec);
    String tableTag = "tbl_" + base;
    String numericalTag = "gev_" + base;
    String exportTag = "exp_" + base;
    String csvPath = WORKDIR + "/" + caseName(spec) + ".csv";

    model.result().table().create(tableTag, "Table");
    model.result().table(tableTag).comments(
        spec[CASE_CW] + " " + spec[CASE_RATE] + "P " + spec[CASE_DIRECTION] + " polarization export");
    model.result().numerical().create(numericalTag, "EvalGlobal");
    model.result().numerical(numericalTag).set("data", "dset5");
    model.result().numerical(numericalTag).set("table", tableTag);
    model.result().numerical(numericalTag).set("expr", new String[]{
        "t",
        "comp1.Q1",
        "comp1.vol",
        "polar",
        "abs(total/liion.Its_ec1)",
        "abs(ohms/liion.Its_ec1)",
        "abs(ohml/liion.Its_ec1)",
        "abs(dl/liion.Its_ec1)",
        "abs(ds/liion.Its_ec1)",
        "abs(RCT/liion.Its_ec1)",
        "abs(total_neg/liion.Its_ec1)",
        "abs(total_pos/liion.Its_ec1)",
        "abs(total_sep/liion.Its_ec1)"
    });
    model.result().numerical(numericalTag).set("descr", new String[]{
        "time_s",
        "capacity_Ah",
        "voltage_V",
        "polarization_V",
        "total_resistance_mOhm",
        "solid_ohmic_mOhm",
        "electrolyte_ohmic_mOhm",
        "electrolyte_diffusion_mOhm",
        "solid_diffusion_mOhm",
        "charge_transfer_mOhm",
        "negative_total_mOhm",
        "positive_total_mOhm",
        "separator_total_mOhm"
    });
    model.result().numerical(numericalTag).setResult();

    model.result().export().create(exportTag, "Table");
    model.result().export(exportTag).set("table", tableTag);
    model.result().export(exportTag).set("filename", csvPath);
    model.result().export(exportTag).set("header", true);
    model.result().export(exportTag).run();
  }

  private static void solveCase(String[] spec) throws Exception {
    Model model = null;
    try {
      System.out.println("CODEX_CASE_START " + caseName(spec));
      model = buildModel();
      configureCase(model, spec);
      model.study("std1").runNoGen();
      exportCase(model, spec);
      model.save(WORKDIR + "/" + caseName(spec) + ".mph");
      System.out.println("CODEX_CASE_DONE " + caseName(spec));
    } finally {
      try {
        ModelUtil.remove("Model");
      } catch (Exception ignored) {
      }
    }
  }

